"""User-facing ORBIT dashboard."""
from __future__ import annotations

DASHBOARD_HTML = '''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ORBIT</title><style>
:root{color-scheme:dark;--bg:#070a10;--card:#101827;--line:#24324a;--text:#edf3fb;--muted:#91a0b7;--accent:#7c9cff;--ok:#43d19a}*{box-sizing:border-box}body{margin:0;font:14px system-ui;background:radial-gradient(circle at 10% 0,#18243b,#070a10 45%);color:var(--text)}button,input,textarea,select{font:inherit}button{border:0;border-radius:9px;padding:10px 14px;background:var(--accent);font-weight:700;cursor:pointer}button.alt{background:#182338;color:var(--text);border:1px solid var(--line)}.app{display:grid;grid-template-columns:220px 1fr;min-height:100vh}.side{padding:22px 14px;border-right:1px solid var(--line);background:#090e17e8}.brand{font-size:27px;font-weight:900;letter-spacing:.1em}.muted{color:var(--muted)}.nav{display:grid;gap:6px;margin-top:28px}.nav button{background:transparent;color:var(--muted);text-align:left}.nav button.active,.nav button:hover{background:#142036;color:var(--text)}.state{margin-top:24px;border:1px solid var(--line);border-radius:12px;padding:12px;background:var(--card)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--ok);margin-right:7px}.main{padding:26px;max-width:1400px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;gap:16px;margin-bottom:20px}.title{font-size:26px;font-weight:850}.actions{display:flex;gap:8px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:linear-gradient(180deg,#111a29,#0c1420);border:1px solid var(--line);border-radius:15px;padding:16px}.label{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.num{font-size:28px;font-weight:850;margin:4px 0}.two{display:grid;grid-template-columns:1.1fr .9fr;gap:12px;margin-top:12px}.list{display:grid;gap:7px}.row{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:10px;border:1px solid var(--line);border-radius:10px;background:#0b1320}.pill{font-size:11px;padding:4px 8px;border-radius:999px;background:#19263b}.ok{background:#103126;color:#9af0ce}.form{display:grid;gap:9px}.field{display:grid;gap:4px}.field label{font-size:12px;color:var(--muted)}input,textarea,select{width:100%;padding:10px;border-radius:9px;border:1px solid var(--line);background:#080e17;color:var(--text)}.chat{height:350px;overflow:auto;border:1px solid var(--line);border-radius:11px;padding:12px;background:#080d15}.msg{padding:9px 11px;border-radius:10px;margin:0 0 8px;white-space:pre-wrap}.user{background:#192b4c;margin-left:15%}.assistant{background:#121d2e;margin-right:10%}.login{position:fixed;inset:0;display:grid;place-items:center;background:#05070ddd;z-index:5}.login.hide{display:none}.loginbox{width:min(420px,calc(100% - 30px));padding:24px;border:1px solid var(--line);border-radius:16px;background:var(--card)}.hide{display:none!important}.toast{position:fixed;right:20px;bottom:20px;padding:12px;background:#142033;border:1px solid var(--line);border-radius:10px;display:none}.toast.show{display:block}@media(max-width:900px){.app{grid-template-columns:1fr}.side{border-right:0;border-bottom:1px solid var(--line)}.grid{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}}@media(max-width:600px){.grid{grid-template-columns:1fr}.main{padding:14px}.top{flex-direction:column}}
</style></head><body>
<div id="login" class="login"><div class="loginbox"><div class="brand">ORBIT</div><p class="muted">Production AI control plane</p><div class="form"><div class="field"><label>API token</label><input id="token" type="password"></div><button onclick="login()">Connect</button></div></div></div>
<div id="app" class="app hide"><aside class="side"><div class="brand">ORBIT</div><div class="muted">AI control plane</div><div class="nav"><button class="active" data-p="overview" onclick="page('overview')">Overview</button><button data-p="models" onclick="page('models')">Models</button><button data-p="inference" onclick="page('inference')">Inference</button><button data-p="requests" onclick="page('requests')">Requests</button></div><div class="state"><span class="dot"></span><b id="state">ready</b><div id="stateDetail" class="muted">Checking…</div></div><button class="alt" style="width:100%;margin-top:14px" onclick="logout()">Sign out</button></aside>
<main class="main"><div class="top"><div><div id="title" class="title">Overview</div><div class="muted">Live ORBIT production control plane</div></div><div class="actions"><button class="alt" onclick="refresh()">Refresh</button><a href="/docs" target="_blank"><button class="alt">API Docs</button></a></div></div>
<div id="overview"><div class="grid"><div class="card"><div class="label">Service</div><div id="service" class="num">—</div></div><div class="card"><div class="label">Models</div><div id="modelsCount" class="num">—</div></div><div class="card"><div class="label">Requests</div><div id="requestsCount" class="num">—</div></div><div class="card"><div class="label">Failures</div><div id="failures" class="num">—</div></div></div><div class="two"><div class="card"><h3>System</h3><div id="system" class="list"></div></div><div class="card"><h3>Readiness</h3><div id="checks" class="list"></div></div></div></div>
<div id="models" class="hide"><div class="two"><div class="card"><h3>Model catalog</h3><div id="modelList" class="list"></div></div><div class="card"><h3>Register model</h3><div class="form"><div class="field"><label>ID</label><input id="mid" value="orbit-demo"></div><div class="field"><label>Display name</label><input id="mname" value="ORBIT Demo Runtime"></div><div class="field"><label>Runtime</label><input id="mrun" value="orbit-demo"></div><div class="field"><label>Capabilities</label><input id="mcaps" value="text-generation,chat,streaming,demo"></div><button onclick="registerModel()">Register</button></div></div></div></div>
<div id="inference" class="hide"><div class="card"><h3>Inference console</h3><div id="chat" class="chat"></div><div class="form" style="margin-top:10px"><select id="chatModel"></select><textarea id="prompt" rows="3" placeholder="Ask ORBIT something…"></textarea><button onclick="send()">Send</button></div></div></div>
<div id="requests" class="hide"><div class="card"><h3>Recent requests</h3><div id="requestList" class="list"></div></div></div>
</main></div><div id="toast" class="toast"></div>
<script>
const S={token:localStorage.getItem('orbit_token')||'',page:'overview'},$=x=>document.getElementById(x);function toast(x){$('toast').textContent=x;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2400)}function login(){S.token=$('token').value.trim();api('/v1/session').then(()=>{localStorage.setItem('orbit_token',S.token);$('login').classList.add('hide');$('app').classList.remove('hide');refresh()}).catch(()=>{S.token='';toast('Invalid token')})}function logout(){S.token='';localStorage.removeItem('orbit_token');$('app').classList.add('hide');$('login').classList.remove('hide')}function hdr(){return {'Content-Type':'application/json','Authorization':'Bearer '+S.token}}async function api(p,o={}){const r=await fetch(p,{...o,headers:{...hdr(),...(o.headers||{})}});const d=await r.json().catch(()=>({detail:r.statusText}));if(r.status===401){logout();throw Error('Authentication required')}if(!r.ok)throw Error(d.detail||'Request failed');return d}function page(p){S.page=p;['overview','models','inference','requests'].forEach(x=>$(x).classList.toggle('hide',x!==p));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.p===p));$('title').textContent=p[0].toUpperCase()+p.slice(1);if(p==='models'||p==='inference')loadModels();if(p==='requests')loadRequests()}async function refresh(){try{const [root,h,m,r,sys]=await Promise.all([fetch('/').then(x=>x.json()),fetch('/health').then(x=>x.json()),api('/v1/metrics'),api('/v1/requests?limit=100'),api('/v1/system')]);$('service').textContent=root.status.toUpperCase();$('modelsCount').textContent=h.checks.find(x=>x.name==='models')?.detail?.split(' ')[0]||0;$('requestsCount').textContent=r.data.length;$('failures').textContent=m.failed_requests||0;$('state').textContent=h.state;$('stateDetail').textContent='All systems healthy';$('checks').innerHTML=h.checks.map(x=>`<div class="row"><span>${x.name}</span><span class="pill ok">${x.status}</span></div>`).join('');$('system').innerHTML=`<div class="row"><span>Platform</span><b>${sys.platform}</b></div><div class="row"><span>Architecture</span><b>${sys.architecture}</b></div><div class="row"><span>Memory</span><b>${sys.memory_bytes?Math.round(sys.memory_bytes/1073741824*10)/10+' GiB':'—'}</b></div>`;renderRequests(r.data);if(S.page==='models'||S.page==='inference')loadModels()}catch(e){toast(e.message)}}function renderRequests(d){$('requestList').innerHTML=d.length?d.map(x=>`<div class="row"><span><b>${x.request_id}</b><br><span class="muted">${x.model||'unknown'} · ${x.runtime||'unknown'}</span></span><span class="pill ${x.state==='completed'?'ok':''}">${x.state}</span></div>`).join(''):'<div class="muted">No requests yet.</div>'}async function loadRequests(){try{renderRequests((await api('/v1/requests?limit=100')).data)}catch(e){toast(e.message)}}async function loadModels(){try{const d=await api('/v1/models');$('modelList').innerHTML=d.data.length?d.data.map(x=>`<div class="row"><span><b>${x.id}</b><br><span class="muted">${x.display_name||x.state}</span></span><span class="pill ${x.state==='ready'?'ok':''}">${x.state}</span></div>`).join(''):'<div class="muted">No models.</div>';$('chatModel').innerHTML=d.data.map(x=>`<option value="${x.id}">${x.display_name||x.id}</option>`).join('')}catch(e){toast(e.message)}}async function registerModel(){try{await api('/v1/models',{method:'POST',body:JSON.stringify({id:$('mid').value,display_name:$('mname').value,modality:'text',capabilities:$('mcaps').value.split(',').map(x=>x.trim()).filter(Boolean),runtimes:[$('mrun').value],tags:['ui']})});toast('Model registered');loadModels();refresh()}catch(e){toast(e.message)}}function esc(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function send(){const p=$('prompt').value.trim(),model=$('chatModel').value;if(!p||!model)return toast('Select a model and enter a message');$('chat').innerHTML+=`<div class="msg user">${esc(p)}</div>`;$('prompt').value='';try{const d=await api('/v1/chat/completions',{method:'POST',body:JSON.stringify({model,messages:[{role:'user',content:p}],stream:false})});$('chat').innerHTML+=`<div class="msg assistant">${esc(d.choices[0].message.content)}</div>`;$('chat').scrollTop=$('chat').scrollHeight;refresh()}catch(e){$('chat').innerHTML+=`<div class="msg assistant">Error: ${esc(e.message)}</div>`}}if(S.token){api('/v1/session').then(()=>{ $('login').classList.add('hide');$('app').classList.remove('hide');refresh()}).catch(()=>logout())}
</script></body></html>'''
